// Only the Android host opts in. The ordinary desktop keeps its saved-path API.
// A failed JSON response must never become a file with a backup extension.
async function androidHostBackupDownload(body) {
  const response = await fetch("/api/backup/export", {
    method: "POST", credentials: "same-origin", mode: "same-origin", redirect: "error", cache: "no-store",
    headers: { "Content-Type": "application/json", Accept: "application/octet-stream" },
    body: JSON.stringify({ ...body, sink: "app" }),
  });
  const type = (response.headers.get("Content-Type") || "").split(";")[0].trim().toLowerCase();
  if (!response.ok || type !== "application/octet-stream" ||
      response.headers.get("Content-Disposition") !== 'attachment; filename="magpie.magpie-backup"') {
    throw new Error(t("Export") + ": " + t("Try again"));
  }
  const blob = await response.blob();
  if (!blob.size) throw new Error(t("Export") + ": " + t("Try again"));
  // Keep a retry button for browsers that require a fresh user gesture. A retry
  // downloads these same sealed bytes; it does not repeat the export POST.
  return () => {
    const a = document.createElement("a");
    const url = URL.createObjectURL(blob);
    try {
      a.href = url;
      a.download = "magpie.magpie-backup";
      document.body.append(a);
      a.click();
    }
    finally {
      a.remove();
      // Revoking immediately can cancel the browser's asynchronous download.
      setTimeout(() => URL.revokeObjectURL(url), 60e3);
    }
  };
}

// A settings tab or the whole view can stay connected while hidden. Never
